import re

def fix_course_name(code_line, prev_lines):
    """If course_name is empty/numeric, try to find it from previous lines."""
    parts = code_line.split()

    # If we already have a name, skip
    time_pos = -1
    for j, p in enumerate(parts):
        if p in ['一','二','三','四','五','六'] and j+1 < len(parts):
            if re.match(r'\d+-\d+', parts[j+1]):
                time_pos = j
                break

    if time_pos <= 0:
        return code_line, None

    before = parts[:time_pos]
    # Check if this is just credits + instructor
    has_name = False
    for p in before[:-1]:  # exclude last element (credits)
        if re.search(r'[\u4e00-\u9fff]', p):
            has_name = True
            break

    if has_name:
        return code_line, None

    # No name found in the line - look at previous lines for continuation
    for pl in prev_lines[-3:]:
        pl = pl.strip()
        if not pl:
            continue
        # Skip lines that are purely exam info
        if '考试日期' in pl and '考试时间' not in pl:
            continue
        if pl.startswith('考试日期:'):
            continue
        # Look for trailing Chinese text (course name continuation)
        # Pattern: text at end of line that's Chinese characters (possibly with numbers/punctuation)
        m = re.search(r'(\u4e00-\u9fff[\u4e00-\u9fff\d\（）《》，。！？、·-]*)\s*(?:考试时间|考试日期|系|学院|部)$', pl)
        if m:
            name_part = m.group(1)
            return name_part, pl
        # Also check simpler pattern: trailing Chinese chars
        m2 = re.search(r'([\u4e00-\u9fff]+)$', pl)
        if m2:
            name_part = m2.group(1)
            return name_part, pl

    return None, None

with open('/app/pdf_text.txt', 'r') as f:
    lines = f.readlines()

# Test with all target codes
for code in ['PHIL119059', 'FORE119008', 'BIOL119008', 'ECON110017', 'BIOL110035', 'CHIN110038', 'ICES110024', 'PHIL119054', 'FINE110037', 'FINE110001', 'MANA110057', 'MANA110058', 'MANA110064', 'BIOL110013', 'MUSE110002', 'ECON110015']:
    found = False
    for i, line in enumerate(lines):
        if code in line and line.startswith(('PHIL','FORE','BIOL','ECON','CHIN','ICES','FINE','MANA','MUSE')):
            found = True
            name_part, source = fix_course_name(line, lines[max(0,i-6):i])
