from openpyxl import Workbook
import os

titles = ['教授', '副教授', '讲师', '助理研究员', '青年研究员', '青年副研究员',
          '研究员', '副研究员', '高级工程师', '工程师', '主管技师',
          '主任医师', '副主任医师', '教授(教学为主型)', '副教授(教学为主型)', '实验师']

def is_title(word):
    return word in titles

with open('/app/pdf_text.txt', 'r') as f:
    lines = f.readlines()

def parse_course_line(line, line_idx=None):
    line = line.strip()
    m = re.match(r'([A-Z]{2,4}[0-9]+\.[0-9]+)\s+(.+)', line)
    if not m:
        return None
    code = m.group(1)
    rest = m.group(2)
    parts = rest.split()

    time_pos = -1
    for j, p in enumerate(parts):
        if p in ['一','二','三','四','五','六'] and j+1 < len(parts):
            if re.match(r'\d+-\d+', parts[j+1]):
                time_pos = j
                break
    if time_pos <= 0:
        return {'Course ID': code}

    before_time = parts[:time_pos]
    instructor_pos = -1
    for j in range(len(before_time)-1, 0, -1):
        if is_title(before_time[j]):
            instructor_pos = j
            break

    if instructor_pos <= 0:
        return {'Course ID': code}

    instructor = before_time[instructor_pos]
    title = before_time[instructor_pos+1] if instructor_pos+1 < len(before_time) else ''

    credits = ''
    credits_pos = -1
    for j in range(instructor_pos-1, 0, -1):
        if before_time[j].isdigit() and int(before_time[j]) <= 5:
            credits_pos = j
            credits = before_time[j]
            break

    course_name = ' '.join(before_time[1:credits_pos]) if credits_pos > 1 else ''

    # If no name found, look at previous lines
    if not course_name and line_idx is not None:
        for pl in lines[max(0, line_idx-5):line_idx]:
            pl = pl.strip()
            if not pl:
                continue
            if pl.startswith('考试日期:'):
                continue
            m_trail = re.search(r'([\u4e00-\u9fff][\u4e00-\u9fff\d\（）《》，。！？、·-]*)', pl)
            if m_trail:
                course_name = m_trail.group(1)
                break

    after_parts = parts[time_pos:]
    class_time = ' '.join(after_parts[:3])

    campus = ''
    for c in ['邯郸校区', '枫林校区', '江湾校区', '张江校区']:
        if c in rest:
            campus = c
            break

    enrollment = ''
    cm = re.search(r'(?:邯郸校区|枫林校区|江湾校区|张江校区)\s+(\d+)', rest)
    if cm:
        enrollment = cm.group(1)

    assessment = ''
    for a in ['开卷', '闭卷', '半开卷', '论文', '视频教学', '随堂考试', '研讨型课程']:
        if a in rest:
            assessment = a
            break

    exam_time = ''
    em = re.search(r'(\d{4}-\d{2}-\d{2})', rest)
    if em:
        exam_time = em.group(1)

    restrictions = ''
    after_rest = rest
    for a in ['开卷', '闭卷', '半开卷', '论文', '视频教学', '随堂考试', '研讨型课程']:
        if a in after_rest:
            idx = after_rest.find(a)
            after_rest = after_rest[idx+len(a):]
            break
    restrictions = after_rest.strip()

    return {
        'Course name': course_name,
        'Course ID': code,
        'Instructor': instructor,
        'Campus': campus,
        'Class Time': class_time,
        'Enrollment': enrollment,
        'Credits': credits,
        'Assessment Method': assessment,
        'Exam Time': exam_time,
        'Course Selection Restrictions': restrictions,
        '_day': parts[time_pos],
        '_time': parts[time_pos+1]
    }

# Fixed courses - use lines from text file
fixed_lines = [
    'COMP130141.01 自然语言处理 2 黄萱菁 教授 一 2-3 [1-16] 邯郸校区 60 闭卷 大数据与人工智能(2023)',
    'COMP130025.01 软件体系结构 2 陈彤兵 讲师 一 4-5 [1-16] 邯郸校区 50 闭卷 23 22 计算机科学与技术',
    'PTSS110080.01 中国共产党历史 2 薛小荣 副教授 一 11-12 [1-15] 邯郸校区 180 思政B 开卷 是',
]
fixed = []
for fl in fixed_lines:
    for li, line in enumerate(lines):
        if fl in line:
            fixed.append(parse_course_line(fl, li))
            break

# Extract tongren courses
tongren_entries = []
in_tongren = False

for i, line in enumerate(lines):
    line_num = i + 1
    if line_num >= 1059:
        in_tongren = True
    if line_num >= 6038:
        in_tongren = False
    if not in_tongren:
        continue

    m = re.match(r'([A-Z]{2,4}[0-9]+\.[0-9]+)', line)
    if not m:
        continue

    parsed = parse_course_line(line, i)
    if parsed and parsed.get('Class Time'):
        dm = re.search(r'(一)\s+(\d+-\d+)\s+\[', line)
