for i, v in enumerate(valid):
    print(f"  {i+1}. {v['Course name']} [{v['Course ID']}] - {v['Class Time']}")

# Create Excel
fields = ['Course name','Course ID','Instructor','Campus','Class Time','Enrollment','Credits','Assessment Method','Exam Time','Course Selection Restrictions']

for idx, opt in enumerate(valid):
